// ===== 1. 策略接口 =====
public interface PaymentStrategy {
    void pay(Order order);
    String channel(); // 返回渠道标识，便于日志和监控
}

// ===== 2. Spring Map 自动收集（最常用） =====
@Component("wechat")
public class WechatPayment implements PaymentStrategy {
    @Override
    public void pay(Order order) { /* 调用微信SDK */ }
    @Override
    public String channel() { return "wechat"; }
}
@Component("alipay")
public class AlipayPayment implements PaymentStrategy {
    @Override
    public void pay(Order order) { /* 调用支付宝SDK */ }
    @Override
    public String channel() { return "alipay"; }
}

@Service
public class PaymentService {
    // Spring 按 beanName 自动收集所有 PaymentStrategy 实现
    private final Map<String, PaymentStrategy> strategyMap;
    private final PaymentStrategy defaultStrategy;

    public PaymentService(Map<String, PaymentStrategy> strategyMap,
                          @Qualifier("wechat") PaymentStrategy defaultStrategy) {
        this.strategyMap = strategyMap;
        this.defaultStrategy = defaultStrategy;
    }

    public void pay(String channel, Order order) {
        // 未命中时走默认策略，而非返回 null
        PaymentStrategy strategy = strategyMap.getOrDefault(channel, defaultStrategy);
        strategy.pay(order);
    }
}

// ===== 3. 枚举注册表（key 受枚举约束，编译期防错） =====
public enum CouponType {
    FULL_REDUCE, DISCOUNT, GIFT;
}
public class CouponFactory {
    private static final Map<CouponType, CouponStrategy> MAP = Map.of(
        CouponType.FULL_REDUCE, new FullReduceStrategy(),
        CouponType.DISCOUNT,    new DiscountStrategy(),
        CouponType.GIFT,        new GiftStrategy()
    );
    public static CouponStrategy of(CouponType type) {
        return Optional.ofNullable(MAP.get(type))
            .orElseThrow(() -> new IllegalArgumentException("不支持的优惠类型: " + type));
    }
}

// ===== 4. Lambda 作为轻量策略 =====
@FunctionalInterface
public interface ValidationStrategy {
    boolean isValid(String s);
}
public class Validator {
    private final ValidationStrategy strategy;
    public Validator(ValidationStrategy strategy) { this.strategy = strategy; }
    public boolean validate(String s) { return strategy.isValid(s); }
}
// 使用：不必为每种校验建类
Validator numericValidator = new Validator(s -> s.matches("\\d+"));
Validator emailValidator = new Validator(s -> s.contains("@"));

// ===== 5. JDK 原生策略模式：Comparator =====
List<String> list = Arrays.asList("c", "a", "b");
list.sort(Comparator.naturalOrder());       // 策略：自然序
list.sort(Comparator.reverseOrder());       // 策略：逆序
list.sort(Comparator.comparingInt(String::length)); // 策略：按长度
